INSERT INTO manga (title, author, genre, description, imageurl) VALUES ('Naruto', 'Masashi Kishimoto', 'Shonen', 'Naruto Uzumaki is a young ninja who seeks recognition from his peers and dreams of becoming the Hokage, the leader of his village.', 'http://localhost:8080/images/manga1.jpg');
INSERT INTO manga (title, author, genre, description, imageurl) VALUES ('One Piece', 'Eiichiro Oda', 'Shonen', 'Monkey D. Luffy is a young pirate with a dream: to prove the legend true and become the Pirate King.', 'http://localhost:8080/images/manga2.jpg');
INSERT INTO manga (title, author, genre, description, imageurl) VALUES ('Bleach', 'Tite Kubo', 'Shonen', 'Ichigo Kurosaki is an ordinary high schooler—until his family is attacked by a Hollow, a corrupt spirit that seeks to devour human souls.', 'http://localhost:8080/images/manga3.jpg');
INSERT INTO manga (title, author, genre, description, imageurl) VALUES ('Attack on Titan', 'Hajime Isayama', 'Shonen', 'In a world where humanity resides within enormous walled cities to protect themselves from Titans, gigantic humanoid creatures, Eren Yeager joins the military to avenge the death of his mother.', 'http://localhost:8080/images/manga4.jpg');
INSERT INTO manga (title, author, genre, description, imageurl) VALUES ('My Hero Academia', 'Kohei Horikoshi', 'Shonen', 'Many years ago, a miracle happened – a shimmering baby was born. Since then, people with special powers – quirks -have been born everywhere. However, alas, not all of them use their abilities for good.… Fortunately, professional heroes are always on guard, who will not allow absolute evil to take over! If you want to become a hero, enroll in the hero academy and unlock your potential!', 'http://localhost:8080/images/manga5.jpg');